let lang=['en','es','it'].includes(new URLSearchParams(location.search).get('lang'))?new URLSearchParams(location.search).get('lang'):'en';
const selections={pub:new Set(),act:new Set()};let expanded={pub:false,act:false};let filtered={pub:[],act:[]};
const t=k=>ui[lang][k]||k, tr=k=>(labels[k]||[k,k,k])[['en','es','it'].indexOf(lang)];
const date=s=>!s?'':s==='Current'?t('current'):/^\d{4}$/.test(String(s))?String(s):String(s).slice(0,10).split('-').reverse().join('/');
const tag=(s,c='')=>`<span class="tag ${c}">${esc(tr(s))}</span>`;
function options(id,values,first){const old=$(id).value;$(id).innerHTML=`<option value="">${esc(first)}</option>`+values.map(x=>`<option value="${esc(x)}">${esc(tr(x))}</option>`).join('');if(values.map(String).includes(old))$(id).value=old;}
function selectedRows(kind){return filtered[kind].filter(x=>selections[kind].has(x.id));}
function renderList(kind){const ispub=kind==='pub',a=ispub?DATA.publications:DATA.activities;const q=$(kind+'-search').value.toLocaleLowerCase();filtered[kind]=a.filter(x=>{if(ispub){return (!q||[x.title,x.authors,x.venue,...x.topics].join(' ').toLocaleLowerCase().includes(q))&&(!$('pub-type').value||x.type===$('pub-type').value)&&(!$('pub-year').value||String(x.year)===$('pub-year').value)&&(!$('pub-topic').value||x.topics.includes($('pub-topic').value));}return (!q||[x.title[lang],x.description[lang],x.organiser,x.location].join(' ').toLocaleLowerCase().includes(q))&&(!$('act-category').value||x.category===$('act-category').value)&&(!$('act-year').value||x.start.slice(0,4)===$('act-year').value);});
const list=filtered[kind],visible=expanded[kind]?list:list.slice(0,6);
$(kind+'-list').innerHTML=visible.map(x=>ispub?pubHTML(x):actHTML(x)).join('')||`<p class="empty">${t('empty')}</p>`;
$(kind+'-count').textContent=`${list.length} ${t('records')} · ${selectedRows(kind).length} ${t('selected')}`;
$(kind+'-more').hidden=list.length<=6;$(kind+'-more').textContent=t(expanded[kind]?'less':'more')+` (${list.length})`;
const n=selectedRows(kind).length;$(kind+'-select').checked=!!list.length&&n===list.length;$(kind+'-select').indeterminate=n>0&&n<list.length;
$(kind+'-list').querySelectorAll('input[type=checkbox]').forEach(el=>el.addEventListener('change',()=>{el.checked?selections[kind].add(el.dataset.id):selections[kind].delete(el.dataset.id);renderList(kind);}));}
function checkbox(x,kind){return `<input type="checkbox" data-id="${esc(x.id)}" aria-label="${esc(t('select')+': '+(kind==='pub'?x.title:x.title[lang]))}" ${selections[kind].has(x.id)?'checked':''}>`;}
function pubHTML(x){return `<article class="record">${checkbox(x,'pub')}<div class="year">${esc(x.year)}</div><div class="recordbody"><h3>${x.doi?`<a href="https://doi.org/${esc(x.doi)}">${esc(x.title)}</a>`:esc(x.title)}</h3><p class="authors">${esc(x.authors)}</p><p class="venue"><i>${esc(x.venue)}</i></p><div class="tags">${tag(x.type,'blue')}${x.topics.map(z=>tag(z,z==='Neuroethics and AI'?'pink':'')).join('')}</div><div class="linkrow">${x.doi?`<a href="https://doi.org/${esc(x.doi)}">DOI ↗</a>`:''}${x.orcid_ids.length?`<a href="https://orcid.org/0000-0002-1594-7382/work/${esc(x.orcid_ids[0])}">ORCID ↗</a>`:(x.sources.find(s=>safe(s))?`<a href="${safe(x.sources.find(s=>safe(s)))}">${t('source')} ↗</a>`:'')}${x.related?`<a href="https://doi.org/${esc(x.related.replace('doi:',''))}">${t('related')} ↗</a>`:''}</div></div></article>`;}
function actHTML(x){return `<article class="record">${checkbox(x,'act')}<div class="year">${esc(x.start.slice(0,4))}</div><div class="recordbody"><div class="tags">${tag(x.category,x.category==='Public outreach'?'pink':x.category==='School engagement'?'green':'blue')}</div><h3>${esc(x.title[lang])}</h3><p class="venue">${date(x.start)}${x.end?' – '+date(x.end):''} · ${esc(x.organiser)}</p><p class="description">${esc(x.description[lang])}</p>${x.location?`<p class="authors">${esc(x.location)}</p>`:''}${safe(x.url)?`<a style="font-size:12px" href="${safe(x.url)}">${esc(x.url_label?.[lang]||t('source'))} ↗</a>`:''}</div></article>`;}
function projectDates(x){return (x.date_scope==='action'?t('actiondates')+': ':t('participation')+': ')+date(x.start)+(x.end?' – '+date(x.end):x.status==='Ongoing'&&x.date_scope!=='contribution'?' – '+t('current'):'');}
function projectHTML(x){return `<article class="record"><span></span><div class="year">${esc(x.start.slice(0,4))}</div><div class="recordbody"><div class="tags">${tag(x.status,'green')}${x.type?tag(x.type,'blue'):''}<span class="tag">${esc([x.funder,x.grant].filter(Boolean).join(' · '))}</span></div><h3>${esc(x.titles?.[lang]||x.title)}</h3><p class="venue">${esc(projectDates(x))} · ${esc(tr(x.role))}</p><p class="description">${esc(x.description[lang])}</p>${safe(x.url)?`<a style="font-size:12px" href="${safe(x.url)}">${t('source')} ↗</a>`:''}</div></article>`;}
function renderMemberships(){
 $('memberships-title').textContent=t('memberships');$('memberships-intro').textContent=t('membershipintro');
 $('membership-grid').innerHTML=DATA.memberships.map(x=>`<article class="membership-card"><div class="membership-top"><span class="membership-acronym">${esc(x.acronym)}</span><span class="membership-since">${t('since')} ${date(x.start)}</span></div><h4><a href="${safe(x.url)}">${esc(x.names?.[lang]||x.name)} ↗</a></h4><p>${esc(x.role[lang])}</p></article>`).join('');
 $('academic-details').innerHTML=`<article><h3>${t('mentoring')}</h3><p>${esc(DATA.content[lang].mentoring)}</p></article><article><h3>${t('reviews')}</h3><p>${esc(DATA.content[lang].grant_reviews)}</p></article>`;
 const cv=$('cv-download');cv.textContent=t('cv');cv.href=DATA.content[lang].cv_url;
}
function render(){document.documentElement.lang=lang;renderMemberships();const c=DATA.content[lang];document.querySelectorAll('[data-lang]').forEach(a=>a.setAttribute('aria-current',String(a.dataset.lang===lang)));$('hero-label').textContent=t('label');$('question').textContent=c.question;$('intro').textContent=c.intro;$('bio').textContent=c.bio;$('research-cta').textContent=t('cta');const ids=['research','publications','projects','engagement','teaching','background','contact'];ids.forEach((id,i)=>$(id).querySelector('h2').textContent=c.headings[i]);$('nav').innerHTML=ids.map((id,i)=>`<a href="#${id}">${esc(c.headings[i])}</a>`).join('');$('research-grid').innerHTML=c.research.map((x,i)=>`<article class="research-item"><span class="symbol" aria-hidden="true">${['◒','∿','◌'][i]}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p></article>`).join('');$('pub-intro').textContent=t('pubintro');$('project-intro').textContent=t('projectintro');
$('pub-search').placeholder=t('pubsearch');$('pub-search').setAttribute('aria-label',t('pubsearch'));$('act-search').placeholder=t('actsearch');$('act-search').setAttribute('aria-label',t('actsearch'));
options('pub-type',[...new Set(DATA.publications.map(x=>x.type))],t('alltypes'));options('pub-year',[...new Set(DATA.publications.map(x=>x.year))].sort((a,b)=>b-a),t('allyears'));options('pub-topic',[...new Set(DATA.publications.flatMap(x=>x.topics))],t('alltopics'));options('act-category',[...new Set(DATA.activities.map(x=>x.category))],t('allcategories'));options('act-year',[...new Set(DATA.activities.map(x=>x.start.slice(0,4)))].sort().reverse(),t('allyears'));
for(const [id,key] of [['pub-type','alltypes'],['pub-year','allyears'],['pub-topic','alltopics'],['act-category','allcategories'],['act-year','allyears']])$(id).setAttribute('aria-label',t(key));
['pub','act'].forEach(k=>{$(k+'-reset').textContent=t('reset');$(k+'-print').textContent=t('print');$(k+'-export').textContent=t('export');renderList(k);});document.querySelectorAll('.select-label').forEach(x=>x.textContent=t('select'));$('project-print').textContent=t('allprojects');
$('project-list').innerHTML=DATA.projects.map(projectHTML).join('');
$('highlight').innerHTML=`<span class="date">22/10/2026 · SANTIAGO</span><h3>${esc(t('highlight'))}</h3><p style="font-size:13px">${esc(t('highlightdesc'))}</p><a href="https://iicsantiago.esteri.it/it/gli_eventi/calendario/slim2026-conferenza-di-chiara-saracini/">${t('programme')}</a>`;
$('teaching-content').innerHTML=`<div><h3>${t('teaching')}</h3><p>${esc(c.service[0])}</p></div><div><h3>${t('service')}</h3>${c.service.slice(1).map(s=>`<p>${esc(s)}</p>`).join('')}</div>`;$('background-list').innerHTML=c.background.map(s=>`<li>${esc(s)}</li>`).join('');$('footer-note').textContent=t('footer');}
function printRecords(kind){let rows=kind==='project'?DATA.projects:(selectedRows(kind).length?selectedRows(kind):filtered[kind]);if(!rows.length)return;const title=t(kind==='pub'?'pubtitle':kind==='act'?'acttitle':'projecttitle');$('print-area').innerHTML=`<div class="print-head"><h1>Chiara Saracini</h1><p>${esc(title)} · ${esc(lang.toUpperCase())} · ${rows.length} ${t('records')}</p><p>CINPSI Neurocog · Universidad Católica del Maule · csaracini@ucm.cl</p></div>`+rows.map(x=>`<article class="print-record">${kind==='pub'?`<h3>${esc(x.title)}</h3><p>${esc(x.citation||x.authors+' ('+x.year+'). '+x.venue)}</p><p>${esc(tr(x.type))}</p>${x.doi?`<a href="https://doi.org/${esc(x.doi)}">https://doi.org/${esc(x.doi)}</a>`:''}`:`<h3>${esc(kind==='act'?x.title[lang]:(x.titles?.[lang]||x.title))}</h3><p>${kind==='project'?esc(projectDates(x)):date(x.start)+(x.end?' – '+date(x.end):'')}</p><p>${esc(x.description[lang])}</p><p>${esc(kind==='act'?x.organiser:x.funder+' · '+x.grant)}</p>${safe(x.url)?`<a href="${safe(x.url)}">${esc(x.url)}</a>`:''}`}</article>`).join('');window.print();}
function csv(kind){const rows=selectedRows(kind).length?selectedRows(kind):filtered[kind];const headers=kind==='pub'?['ID',t('title'),'Authors','Year','Type','Venue','DOI']:[ 'ID',t('title'),t('description'),t('start'),t('end'),t('category'),t('url')];const data=rows.map(x=>kind==='pub'?[x.id,x.title,x.authors,x.year,tr(x.type),x.venue,x.doi]:[x.id,x.title[lang],x.description[lang],date(x.start),date(x.end),tr(x.category),x.url]);const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+[headers,...data].map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`chiara-saracini-${kind}-${lang}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
document.querySelectorAll('[data-lang]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();lang=a.dataset.lang;const u=new URL(location.href);u.searchParams.set('lang',lang);try{history.replaceState(null,'',u);}catch{}render();}));
window.addEventListener('popstate',()=>{lang=new URLSearchParams(location.search).get('lang')||'en';if(!ui[lang])lang='en';render();});
for(const kind of ['pub','act']){[kind+'-search',...(kind==='pub'?['pub-type','pub-year','pub-topic']:['act-category','act-year'])].forEach(id=>$(id).addEventListener(id.endsWith('search')?'input':'change',()=>{expanded[kind]=true;renderList(kind);}));$(kind+'-reset').onclick=()=>{document.querySelectorAll(`#${kind==='pub'?'publications':'engagement'} .tools input, #${kind==='pub'?'publications':'engagement'} .tools select`).forEach(el=>el.value='');expanded[kind]=false;renderList(kind);};$(kind+'-more').onclick=()=>{expanded[kind]=!expanded[kind];renderList(kind);};$(kind+'-select').onchange=e=>{filtered[kind].forEach(x=>e.target.checked?selections[kind].add(x.id):selections[kind].delete(x.id));renderList(kind);};$(kind+'-print').onclick=()=>printRecords(kind);$(kind+'-export').onclick=()=>csv(kind);}
$('project-print').onclick=()=>printRecords('project');
// Request Drive's current file on each activation, without a repository PDF copy.
// The file ID must be preserved by uploading a new version in Drive.
function freshCVLink(){const u=new URL(DATA.content[lang].cv_url);u.searchParams.set('_',Date.now().toString());$('cv-download').href=u.href;}
['pointerdown','click','auxclick','contextmenu'].forEach(type=>$('cv-download').addEventListener(type,freshCVLink));

// Fixed visual identity; ignore earlier browser-local preview choices.
document.body.dataset.palette='lilac';document.body.dataset.font='pangolin';
document.documentElement.style.setProperty('--link','#c60070');
render();


